  inputs:
    login: ${environments.logins.azure.azure.login}
    clientId: aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee
    lifetimeInDays: 180

fn::rotate::snowflake-user:
  inputs:
    login: ${environments.logins.snowflake.snowflake.login}
    targetUser: ESC_ROTATION_DEMO_USER
